{"name": "create_theme_analyst_role_and_permissions", "query": "
-- ============================================================
-- STEP 1: CONFIGURE theme_analyst ROLE & PERMISSIONS
-- ============================================================

-- Ensure role exists (idempotent)
DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'theme_analyst') THEN
    CREATE ROLE theme_analyst;
  END IF;
END
$$;

-- Revoke any existing broad permissions to start clean
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM theme_analyst;

-- Grant SELECT only on reference tables
GRANT SELECT ON public.lego_themes         TO theme_analyst;
GRANT SELECT ON public.lego_colors         TO theme_analyst;
GRANT SELECT ON public.lego_parts          TO theme_analyst;
GRANT SELECT ON public.lego_part_categories TO theme_analyst;

-- Grant SELECT only on main data tables (RLS will further restrict rows)
GRANT SELECT ON public.lego_sets            TO theme_analyst;
GRANT SELECT ON public.lego_inventories     TO theme_analyst;
GRANT SELECT ON public.lego_inventory_parts TO theme_analyst;

-- Explicitly deny any write permissions (no INSERT, UPDATE, DELETE)
REVOKE INSERT, UPDATE, DELETE ON public.lego_themes          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_colors          FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_parts           FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_part_categories FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_sets            FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_inventories     FROM theme_analyst;
REVOKE INSERT, UPDATE, DELETE ON public.lego_inventory_parts FROM theme_analyst;

-- Grant USAGE on the public schema so the role can access objects
GRANT USAGE ON SCHEMA public TO theme_analyst;
"}

{"query": "
-- ============================================================
-- VERIFICATION TEST 3: Simulate theme_analyst data access
-- using SET ROLE within a single transaction block
-- ============================================================
-- This simulates what theme_analyst sees by temporarily switching roles

DO $$
DECLARE
  v_sets_count       integer;
  v_inv_count        integer;
  v_parts_count      integer;
  v_technic_count    integer;
  v_themes_count     integer;
  v_colors_count     integer;
  v_star_wars_set1   text;
  v_star_wars_set2   text;
BEGIN
  -- Switch to theme_analyst role
  SET LOCAL ROLE theme_analyst;

  -- Count Star Wars sets visible to theme_analyst
  SELECT COUNT(*) INTO v_sets_count FROM public.lego_sets;

  -- Get actual set numbers
  SELECT MIN(set_num) INTO v_star_wars_set1 FROM public.lego_sets;
  SELECT MAX(set_num) INTO v_star_wars_set2 FROM public.lego_sets;

  -- Count inventories visible to theme_analyst
  SELECT COUNT(*) INTO v_inv_count FROM public.lego_inventories;

  -- Count inventory parts visible to theme_analyst
  SELECT COUNT(*) INTO v_parts_count FROM public.lego_inventory_parts;

  -- Count Technic sets (should be 0 - blocked by RLS)
  SELECT COUNT(*) INTO v_technic_count FROM public.lego_sets WHERE theme_id = 1;

  -- Count reference tables (should be full data)
  SELECT COUNT(*) INTO v_themes_count FROM public.lego_themes;
  SELECT COUNT(*) INTO v_colors_count FROM public.lego_colors;

  RAISE NOTICE '=== THEME_ANALYST ROLE ACCESS VERIFICATION ===';
  RAISE NOTICE '';
  RAISE NOTICE '📊 DATA TABLE RESULTS:';
  RAISE NOTICE '  lego_sets visible:            % rows (expected: 2)', v_sets_count;
  RAISE NOTICE '    ↳ Set 1: %',  v_star_wars_set1;
  RAISE NOTICE '    ↳ Set 2: %',  v_star_wars_set2;
  RAISE NOTICE '  lego_inventories visible:     % rows (expected: 2)', v_inv_count;
  RAISE NOTICE '  lego_inventory_parts visible: % rows (expected: 3)', v_parts_count;
  RAISE NOTICE '';
  RAISE NOTICE '🔒 CROSS-THEME ISOLATION:';
  RAISE NOTICE '  Technic sets (theme_id=1) visible: % rows (expected: 0)', v_technic_count;
  RAISE NOTICE '';
  RAISE NOTICE '📚 REFERENCE TABLE RESULTS (no RLS):';
  RAISE NOTICE '  lego_themes accessible:       % rows (expected: 614)', v_themes_count;
  RAISE NOTICE '  lego_colors accessible:       % rows (expected: 135)', v_colors_count;
  RAISE NOTICE '';
  RAISE NOTICE '✅ SECURITY CHECKS:';
  RAISE NOTICE '  Sets = 2:          %', CASE WHEN v_sets_count = 2 THEN 'PASS ✅' ELSE 'FAIL ❌' END;
  RAISE NOTICE '  Technic blocked:   %', CASE WHEN v_technic_count = 0 THEN 'PASS ✅' ELSE 'FAIL ❌' END;
  RAISE NOTICE '  Inventories = 2:   %', CASE WHEN v_inv_count = 2 THEN 'PASS ✅' ELSE 'FAIL ❌' END;
  RAISE NOTICE '  Parts = 3:         %', CASE WHEN v_parts_count = 3 THEN 'PASS ✅' ELSE 'FAIL ❌' END;
  RAISE NOTICE '  Themes readable:   %', CASE WHEN v_themes_count = 614 THEN 'PASS ✅' ELSE 'FAIL ❌' END;
  RAISE NOTICE '  Colors readable:   %', CASE WHEN v_colors_count = 135 THEN 'PASS ✅' ELSE 'FAIL ❌' END;
END;
$$;
"}
